import os
from web3 import Web3
w3 = Web3(Web3.HTTPProvider(os.environ.get('ETH_RPC_URL', 'http://localhost:8545')))
PENDING_DIR = os.environ.get('PENDING_TRANSFER_DIR', './pending_transfers')

def _clear_pending_draft(to_address: str) -> None:
    # Remove the queued draft file for this recipient once the transfer is sent
    draft = os.path.join(PENDING_DIR, Web3.to_checksum_address(to_address) + '.json')
    if os.path.exists(draft):
        os.remove(draft)

def broadcast_eth_transfer(to_address: str, amount_eth: float, private_key: str) -> dict:
    if not Web3.is_address(to_address):
        return {'ok': False, 'error': 'invalid recipient address'}
    if amount_eth is None or amount_eth <= 0:
        return {'ok': False, 'error': 'amount must be positive'}
    if not private_key:
        return {'ok': False, 'error': 'private key required'}
    account = w3.eth.account.from_key(private_key)
    value = w3.to_wei(amount_eth, 'ether')
    gas_price = w3.eth.gas_price
    balance = w3.eth.get_balance(account.address)
    if balance < value + gas_price * 21000:
        return {'ok': False, 'error': 'insufficient balance'}
    tx = {'to': Web3.to_checksum_address(to_address), 'value': value, 'gas': 21000, 'gasPrice': gas_price, 'nonce': w3.eth.get_transaction_count(account.address), 'chainId': w3.eth.chain_id}
    signed = account.sign_transaction(tx)
    tx_hash = w3.eth.send_raw_transaction(signed.raw_transaction)
    _clear_pending_draft(to_address)
    return {'ok': True, 'tx_hash': tx_hash.hex()}
